#include "physics/OriginalVehiclePhysics.h"
#include "OriginalGameCar.h"
#include <fstream>
#include <iostream>
#include <cstring>
#include <stdexcept>
namespace P=r3d::physics;namespace G=r3d::game::originalrace::source;
template<class S,class D> static bool copyClutch(const S&s,D&d){if constexpr(requires{s.clutchLocked;s.clutchStrength;d.clutchLocked;d.clutchStrength;}){d.clutchLocked=s.clutchLocked;d.clutchStrength=s.clutchStrength;return true;}return false;}
static float value(unsigned u){float v;std::memcpy(&v,&u,4);return v;}
static unsigned word(float v){unsigned u;std::memcpy(&u,&v,4);return u;}
static void vec(std::ostream&o,P::Vec3 v){o<<'['<<word(v.x)<<','<<word(v.y)<<','<<word(v.z)<<']';}
static void quat(std::ostream&o,P::Quat q){o<<'['<<word(q.x)<<','<<word(q.y)<<','<<word(q.z)<<','<<word(q.w)<<']';}
int main(int argc,char**argv){try{if(argc!=3 && argc!=4)return 2;std::ifstream in(argv[1]);std::ofstream out(argv[2]);unsigned c,u;while(in>>c){P::Quat q;P::Vec3 omega;float damp[3];for(float*v:{&q.x,&q.y,&q.z,&q.w,&omega.x,&omega.y,&omega.z,&damp[0],&damp[1],&damp[2]}){in>>u;*v=value(u);}unsigned roll,pitch,clutch,strength;in>>roll>>pitch>>clutch>>strength;P::WorldDescription d;d.gravity=0;d.includeDeathPlane=false;d.startPosition={0,0,5};auto&v=d.vehicle;v.mass=1000;v.halfExtents={1,1,.25F};v.bodyLinearDamping=v.bodyAngularDamping=0;v.differentialRatio=3.42F;v.idlingRpm=1000;v.maximumRpm=7000;v.wheelContactsEnabled=false;v.maximumTorque=v.restBrakeTorque=v.brakeTorque=0;for(int i=0;i<4;++i){P::WheelDescription w;w.position={i<2?1.F:-1.F,i%2?1.F:-1.F,-.5F};w.radius=.5F;w.width=.2F;w.suspensionTravel=.4F;w.inverseMass=1;w.flags=0;w.longitudinalTire={1.F,.02F,2.F,.01F,0.F};w.lateralTire=w.longitudinalTire;w.driven=w.steering=i<2;v.wheels.push_back(w);}P::TriangleMesh floor;floor.vertices={{-500,-500,-1000},{500,-500,-1000},{500,500,-1000},{-500,500,-1000}};floor.indices={0,1,2,0,2,3};d.collisionMeshes.push_back(floor);std::string error;auto world=P::createOriginalVehicleWorld(d,error);if(!world)throw std::runtime_error(error);world->synchronizeNetworkVehicle(0,{0,0,5},q,{0,0,0},{0,0,0},true);world->addAngularVelocity(0,omega);auto before=world->vehicle();G::GameCar car;G::GameCar::MotorDescription motor;motor.maximumTorque=motor.brakeTorque=motor.restBrakeTorque=0;car.ConfigureMotor(motor);G::GameCar::DynamicsDescription dynamics;dynamics.angularDamping={{damp[0],damp[1],damp[2]}};dynamics.clampRollAngle=value(roll);dynamics.clampPitchAngle=value(pitch);std::vector<G::GameCar::WheelDynamics> ws;for(const auto&w:v.wheels){G::GameCar::WheelDynamics wd;wd.positionX=w.position.x;wd.driven=w.driven;wd.steering=w.steering;wd.radius=w.radius;ws.push_back(wd);}car.BindWheels(std::vector<bool>(4,false),std::vector<bool>(4,false));car.ConfigureDynamics(dynamics,ws);if(clutch)car.LockClutch(value(strength));unsigned callbacks=0;world->setVehicleFixedStepController([&](std::size_t,float dt,const P::VehicleInput&,const P::VehicleFixedStepState& state){++callbacks;P::VehicleDriveCommand cmd;cmd.applyAngularStabilization=true;cmd.originalGameCarStabilization=true;G::GameCar::FixedStepState st;st.signedSpeed=state.signedSpeed;st.steeringSignedSpeed=state.steeringSignedSpeed;st.absoluteSpeed=state.absoluteSpeed;st.horizontalSpeed=state.horizontalSpeed;st.anyWheelContact=state.anyWheelContact;st.allWheelContact=state.allWheelContact;st.drivenWheelContact=state.drivenWheelContact;st.firstDrivenWheelContact=state.firstDrivenWheelContact;G::GameCar::FixedStepInput input;input.manualSteering=true;auto drive=car.OnFixedStepDrive(dt,input,st);cmd.angularDamping=drive.angularDamping;cmd.clampRollAngle=drive.clampRollAngle;cmd.clampPitchAngle=drive.clampPitchAngle;copyClutch(drive,cmd);
if(argc==4){
 const std::string mode=argv[3];
 if(mode=="inject-clutch" || mode=="inject-unmarked"){cmd.clutchLocked=clutch!=0;cmd.clutchStrength=value(strength);}
 if(mode=="inject-unmarked" || mode=="clear-unmarked")cmd.originalGameCarStabilization=false;
 if(mode=="clear-unmarked"){cmd.clutchLocked=false;cmd.clutchStrength=0;}
}
return cmd;});for(unsigned tick=0;tick<26;++tick){
if(tick){world->synchronizeNetworkVehicle(0,{0,0,5},q,{0,0,0},{0,0,0},true);world->addAngularVelocity(0,omega);}
world->step(1.F/60,P::VehicleInput{});auto after=world->vehicle();out<<"{\"case\":"<<c<<",\"tick\":"<<tick<<",\"clutch_locked_after\":"<<(car.IsClutchLocked()?"true":"false")<<",\"clutch_time_word\":"<<word(car.GetClutchTime())<<",\"callbacks\":"<<callbacks<<",\"rotation_before\":";quat(out,before.body.rotation);out<<",\"omega_before\":";vec(out,omega);out<<",\"cached_momentum_before\":";vec(out,before.angularMomentum);out<<",\"rotation_after_step\":";quat(out,after.body.rotation);out<<",\"momentum_after_step\":";vec(out,after.angularMomentum);out<<",\"position_after_step\":";vec(out,after.body.position);out<<"}\n";}}return out.good()?0:4;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 3;}}
